# Utils
_dcgmIntCheckReturn = dcgm_structs._dcgmCheckReturn
dcgmDeviceConfig_t = dcgm_structs.c_dcgmDeviceConfig_v2
dcgmRecvUpdates_t = dcgm_structs._dcgmRecvUpdates_t
